const ICON_MAP: Record<string, (props: IconProps) => JSX.Element> = {
  MagentaTV: MagentaTVIcon,
  Netflix: NetflixIcon,
  YouTube: YouTubeIcon,
  "Disney+": DisneyPlusIcon,
  "Prime Video": PrimeVideoIcon,
  Spotify: SpotifyIcon,
  ZDF: ZDFIcon,
  ARD: ARDIcon,
};

/**
 * Renders the SVG brand icon for a given app label, or an emoji fallback.
 */
export function AppIcon({
  label,
  fallbackEmoji,
  className = "w-5 h-5",
}: {
  label: string;
  fallbackEmoji?: string;
  className?: string;
}) {
  const Component = ICON_MAP[label];
  if (Component) {
    return <Component className={className} />;
  }
  return <span>{fallbackEmoji ?? "📦"}</span>;
}

export function hasAppSvgIcon(label: string): boolean {
  return label in ICON_MAP;
}
